/**
 * Verifies the gig-section images generated by scripts/fetch-gig-images.mjs:
 *   1. every planned file exists in public/blog/ and in the standalone tree the
 *      production server actually serves from (.next/standalone/public/blog/)
 *   2. every file is >20 KB with sane dimensions (not a saved error page)
 *   3. the pollinations watermark is gone from the bottom-right corner
 *   4. QUALITY: flatness + sharpness metrics, reported worst-first, so blurry or
 *      prompt-ignoring frames can be re-rolled with
 *        SEED_EXTRA=<n> node scripts/fetch-gig-images.mjs --force --only=<file>
 *
 * Exit code 1 if a structural check fails.
 *
 * Run: node scripts/verify-gig-images.mjs
 */
import { existsSync, statSync } from 'node:fs';
import { join } from 'node:path';
import sharp from 'sharp';
import { gigImages } from './gig-images-plan.mjs';

const PUBLIC_BLOG = join(process.cwd(), 'public', 'blog');
const STANDALONE_BLOG = join(process.cwd(), '.next', 'standalone', 'public', 'blog');

const MIN_BYTES = 20 * 1024;
const problems = [];
const quality = [];

for (const img of gigImages) {
  const dest = join(PUBLIC_BLOG, img.file);

  if (!existsSync(dest)) {
    problems.push(`missing: ${img.file}`);
    continue;
  }
  const size = statSync(dest).size;
  if (size < MIN_BYTES) problems.push(`too small (${size}B): ${img.file}`);

  if (existsSync(STANDALONE_BLOG)) {
    const s = join(STANDALONE_BLOG, img.file);
    if (!existsSync(s)) problems.push(`not copied to standalone: ${img.file}`);
    else if (statSync(s).size !== size) problems.push(`standalone size mismatch: ${img.file}`);
  }

  try {
    const meta = await sharp(dest).metadata();
    if ((meta.width || 0) < 640 || (meta.height || 0) < 300) {
      problems.push(`odd dims ${meta.width}x${meta.height}: ${img.file}`);
    }

    // Watermark lives in the bottom-right corner; the 8% trim should remove it.
    const { data, info } = await sharp(dest).raw().toBuffer({ resolveWithObject: true });
    const { width, height, channels } = info;
    const x0 = Math.floor(width * 0.86);
    const y0 = Math.floor(height * 0.94);
    let bright = 0;
    for (let y = y0; y < height; y++) {
      for (let x = x0; x < width; x++) {
        const i = (y * width + x) * channels;
        if (data[i] > 205 && data[i + 1] > 205 && data[i + 2] > 205) bright++;
      }
    }
    if (bright > 2500) problems.push(`possible watermark remnant (${bright}px): ${img.file}`);

    // Quality proxies: stdev of luminance (flat = likely a dead/prompt-ignoring
    // frame) and stdev of a Laplacian (low = blurry / out of focus).
    const flat = (await sharp(dest).grayscale().stats()).channels[0].stdev;
    const blur = (
      await sharp(dest)
        .grayscale()
        .convolve({ width: 3, height: 3, kernel: [0, 1, 0, 1, -4, 1, 0, 1, 0], scale: 1, offset: 128 })
        .stats()
    ).channels[0].stdev;
    quality.push({ file: img.file, flat: Math.round(flat * 10) / 10, blur: Math.round(blur * 10) / 10 });
  } catch (err) {
    problems.push(`unreadable: ${img.file} ${err?.message || err}`);
  }
}

if (quality.length) {
  console.log('\nQuality, worst sharpness first (re-roll the bottom rows):');
  console.log('  sharpness  contrast  file');
  quality
    .sort((a, b) => a.blur - b.blur)
    .forEach((q, i) => {
      const flag = i < 5 ? '  <-- review' : '';
      console.log(`  ${String(q.blur).padStart(8)}  ${String(q.flat).padStart(8)}  ${q.file}${flag}`);
    });
}

if (problems.length) {
  console.error(`\nFAIL - ${problems.length} structural problem(s) of ${gigImages.length} images:`);
  for (const p of problems) console.error('  ' + p);
  process.exitCode = 1;
} else {
  console.log(`\nOK - all ${gigImages.length} gig images present, sized, copied and watermark-free.`);
}
